public class StringPoolMemoryDemo {
    public static void main(String[] args) {
        // String Literals share the pooled object
        String s1 = "LearnBySelf";
        String s2 = "LearnBySelf";

        // Explicit new allocation in general Heap
        String s3 = new String("LearnBySelf");

        System.out.println("s1 == s2 (both in pool): " + (s1 == s2)); // true
        System.out.println("s1 == s3 (pool vs heap): " + (s1 == s3));  // false

        // Using intern() to retrieve the pooled reference
        String s4 = s3.intern();
        System.out.println("s1 == s4 (after intern): " + (s1 == s4));  // true

        // Compile-time literal concatenation vs runtime concatenation
        String c1 = "Learn" + "BySelf"; // Computed at compile-time into "LearnBySelf"
        System.out.println("s1 == c1 (compile-time constant): " + (s1 == c1)); // true

        String prefix = "Learn";
        String c2 = prefix + "BySelf"; // Computed at runtime -> new Heap object!
        System.out.println("s1 == c2 (runtime expression): " + (s1 == c2)); // false
    }
}

