practice.solutionCode:
public class PracticePoolMemory {
    public static void main(String[] args) {
        String pooled = "LearnBySelf";
        String heapObj = new String("LearnBySelf");
        System.out.println("Before intern: " + (heapObj == pooled));
        String interned = heapObj.intern();
        System.out.println("After intern: " + (interned == pooled));
    }
}

