practiceProblems.solutionCode:
public class PoolReferenceCounter {
    public static void main(String[] args) {
        String[] tags = {"java", "java", "spring", "spring", "java"};
        int count = 0;
        for (String tag : tags) {
            if (tag == tags[0]) {
                count++;
            }
        }
        System.out.println("Matching pool references: " + count);
    }
}

